Files["blockos/bin/bdrive.lua"] = [[
-- bdrive: BlockDrive from the terminal. Remote paths may name a server: datacenter:Shared/a.txt
-- (otherwise the only paired server is used).

local Client = BlockOS.Require("cloud/client")
local Drive = BlockOS.Require("cloud/drive")
local Auth = BlockOS.Require("cloud/auth")
local Protocol = BlockOS.Require("cloud/protocol")

local Args = { ... }
local Command = table.remove(Args, 1)

local function Usage()
	print("Usage: bdrive <command>")
	print("  servers               paired servers")
	print("  discover              servers in range")
	print("  pair <hostname>       pair with a server")
	print("  forget <hostname>     unpair")
	print("  info                  space and access")
	print("  ls [path]             list a folder")
	print("  cat <path>            print a text file")
	print("  get <path> [local]    download")
	print("  put <local> [path]    upload")
	print("  mkdir, rm <path>      make folder, delete")
	print("  mv, cp <from> <to>    move or copy")
end

local function Die(Err)
	printError(Protocol.Describe(Err))
	error("", 0)
end

local function FindServer(Name)
	for _, Server in ipairs(Client.List()) do
		if (Server.Hostname == Name or Server.Name == Name) then return Server end
	end
	return nil
end

-- Splits "host:path" into a server and a remote path.
local function Resolve(Spec)
	Spec = Spec or ""
	local Host, Remote = Spec:match("^([%w%-_]+):(.*)$")
	local Server
	if (Host) then
		Server = FindServer(Host)
		if (not Server) then Die("Not paired with " .. Host) end
	else
		local List = Client.List()
		if (#List == 0) then Die("Not paired with any server. Run: bdrive pair <hostname>") end
		if (#List > 1) then Die("Several servers are paired; write hostname:path") end
		Server, Remote = List[1], Spec
	end
	return Server, Remote
end

local function Bar(Label)
	local _, Y = term.getCursorPos()
	return function(Done, Total)
		term.setCursorPos(1, Y)
		term.clearLine()
		write(Label .. " " .. math.floor(Done / math.max(Total, 1) * 100) .. "%")
	end
end

local function Check(Result, Err)
	if (Result == nil) then Die(Err) end
	return Result
end

local function Run()
	if (Command == "servers") then
		for _, Server in ipairs(Client.List()) do
			local Ok = Client.Hello(Server)
			print(Server.Hostname .. "  " .. Client.Title(Server) .. "  #" .. Server.ComputerID .. "  " .. (Ok and (Server.Permission or "") or "offline"))
		end
	elseif (Command == "discover") then
		local Nodes = Check(Client.Discover(2))
		if (#Nodes == 0) then print("No servers answered.") end
		for _, Node in ipairs(Nodes) do
			print(Node.Hostname .. "  " .. Node.Name .. "  #" .. Node.ComputerID .. (Node.Paired and "  (paired)" or ""))
		end
	elseif (Command == "pair" and Args[1]) then
		local Target
		for _, Node in ipairs(Check(Client.Discover(2))) do
			if (Node.Hostname == Args[1]) then Target = Node end
		end
		if (not Target) then Die("No server called " .. Args[1] .. " answered.") end
		local Session = Check(Client.StartPairing(Target))
		print("Ask the administrator of " .. Target.Name .. " to approve this computer with the code:")
		print()
		print("    " .. Auth.FormatCode(Session.Code))
		print()
		print("Waiting (Ctrl+T to cancel)...")
		local Server = Check(Client.WaitPairing(Session))
		print("Paired with " .. Client.Title(Server) .. " (" .. Server.Permission .. ").")
	elseif (Command == "forget" and Args[1]) then
		local Server = FindServer(Args[1])
		if (not Server) then Die("Not paired with " .. Args[1]) end
		Client.Forget(Server.NodeID, true)
		print("Forgot " .. Args[1] .. ".")
	elseif (Command == "info") then
		local Server = Resolve(Args[1])
		local Info = Check(Drive.Info(Server))
		print(Client.Title(Server) .. ": " .. Info.Free .. " bytes free, " .. (Info.Permission == "write" and "read/write" or "read only"))
		print("Shares: " .. table.concat(Info.Shares, ", "))
	elseif (Command == "ls") then
		local Server, Remote = Resolve(Args[1])
		local Listing = Check(Drive.List(Server, Remote))
		for _, Entry in ipairs(Listing.Entries) do
			if (term.isColor()) then term.setTextColor(Entry.Dir and colors.lightBlue or colors.white) end
			print(Entry.Dir and (Entry.Name .. "/") or (Entry.Name .. "  " .. Entry.Size))
		end
		term.setTextColor(colors.white)
	elseif (Command == "cat" and Args[1]) then
		local Server, Remote = Resolve(Args[1])
		print(Check(Drive.ReadText(Server, Remote)))
	elseif (Command == "get" and Args[1]) then
		local Server, Remote = Resolve(Args[1])
		local Target = shell.resolve(Args[2] or Remote:match("[^/]*$"))
		local Size = Check(Drive.Download(Server, Remote, Target, { OnProgress = Bar("Downloading") }))
		print()
		print("Saved " .. Size .. " bytes to /" .. Target)
	elseif (Command == "put" and Args[1]) then
		local Source = shell.resolve(Args[1])
		local Server, Remote = Resolve(Args[2] or fs.getName(Source))
		if (Remote == "" or Remote:sub(-1) == "/") then Remote = Remote .. fs.getName(Source) end
		local Entry = Check(Drive.Upload(Server, Source, Remote, { Overwrite = true, OnProgress = Bar("Uploading") }))
		print()
		print("Uploaded " .. Entry.Size .. " bytes to " .. Remote)
	elseif (Command == "mkdir" and Args[1]) then
		local Server, Remote = Resolve(Args[1])
		Check(Drive.MakeDir(Server, Remote))
	elseif (Command == "rm" and Args[1]) then
		local Server, Remote = Resolve(Args[1])
		Check(Drive.Delete(Server, Remote))
	elseif ((Command == "mv" or Command == "cp") and Args[1] and Args[2]) then
		local Server, From = Resolve(Args[1])
		local _, To = Resolve(Args[2])
		Check((Command == "mv" and Drive.Move or Drive.Copy)(Server, From, To))
	else
		Usage()
	end
end

local Ok, Err = pcall(Run)
if (not Ok and Err ~= "") then printError(Err) end
]]
Files["blockos/lib/cloud/auth.lua"] = [[
-- BlockCloud authentication primitives built on the BlockOS SHA-256 library:
-- random IDs and nonces, pairing codes, key derivation, HMAC signatures and optional
-- ChaCha20 encryption. See docs/BLOCKCLOUD.md for what these do and do not protect against.

local Sha256 = BlockOS.Require("sha256")
local Codec = BlockOS.Require("cloud/codec")
local Config = BlockOS.Require("config")

local Auth = {}

Auth.PoolPath = "/blockos/data/cloud/entropy.dat"
-- No 0/O, 1/I/L: codes are read off one screen and typed into another.
Auth.Alphabet = "23456789ABCDEFGHJKMNPQRSTUVWXYZ"
Auth.CodeLength = 8

local Pool = nil
local Counter = 0

-- Mixes whatever unpredictability CC: Tweaked offers into a persisted pool: wall-clock and CPU
-- time, the computer ID, Java identity hashes of fresh tables, math.random, and the previous pool.
function Auth.Stir(Extra)
	if (not Pool) then
		local Saved = Config.ReadText(Auth.PoolPath)
		Pool = (Saved and Codec.FromHex(Saved)) or ""
	end
	Counter = Counter + 1
	Pool = Sha256.Digest(table.concat({
		Pool, tostring(os.epoch and os.epoch("utc") or 0), tostring(os.clock()), tostring(os.getComputerID()),
		tostring({}), tostring({}), tostring(math.random(0, 2 ^ 30)), tostring(Counter), tostring(Extra or "")
	}, "|"))
end

local function SavePool()
	Config.WriteText(Auth.PoolPath, Codec.ToHex(Sha256.Hmac(Pool, "persist")))
end

function Auth.RandomBytes(Count)
	Auth.Stir()
	local Out = {}
	local Total = 0
	local Block = 0
	while (Total < Count) do
		Block = Block + 1
		local Bytes = Sha256.Hmac(Pool, "out|" .. Counter .. "|" .. Block)
		Out[#Out + 1] = Bytes
		Total = Total + #Bytes
	end
	if (Counter % 8 == 1) then SavePool() end
	return table.concat(Out):sub(1, Count)
end

function Auth.RandomHex(Bytes)
	return Codec.ToHex(Auth.RandomBytes(Bytes))
end

-- A fresh one-time pairing code such as "K7QM2X9D". Rejection sampling keeps it uniform.
function Auth.PairingCode()
	local Chars = {}
	while (#Chars < Auth.CodeLength) do
		for Byte in Auth.RandomBytes(16):gmatch(".") do
			local Value = Byte:byte()
			if (Value < 31 * 8 and #Chars < Auth.CodeLength) then
				local Index = Value % 31 + 1
				Chars[#Chars + 1] = Auth.Alphabet:sub(Index, Index)
			end
		end
	end
	return table.concat(Chars)
end

function Auth.FormatCode(Code)
	return Code:sub(1, 4) .. "-" .. Code:sub(5)
end

-- Accepts what an admin types: any case, with or without the dash or spaces.
function Auth.CleanCode(Text)
	return (tostring(Text or ""):upper():gsub("[^%w]", ""))
end

-- The pairing secret both sides compute from the code. The code itself never goes over the air.
function Auth.DeriveKey(Code, RequestID, ClientNonce, ServerNonce)
	return Sha256.Hmac(Code, "blockcloud-pair|" .. RequestID .. "|" .. ClientNonce .. "|" .. ServerNonce)
end

-- Lets the server tell a mistyped code from the right one when the admin approves.
function Auth.CodeCheck(Code, ClientNonce)
	return Codec.ToHex(Sha256.Hmac(Code, "blockcloud-check|" .. ClientNonce))
end

-- Proof sent with an approval, so the client knows the real server (holding the code) approved it.
function Auth.ApprovalProof(Key, RequestID, ClientID, Permission)
	return Codec.ToHex(Sha256.Hmac(Key, "approved|" .. RequestID .. "|" .. ClientID .. "|" .. Permission))
end

local KeyCache = {}

-- Separate signing and encryption keys derived from one pairing key (raw bytes or hex).
function Auth.Keys(Master)
	if (#Master == 64 and not Master:find("[^%x]")) then Master = Codec.FromHex(Master) end
	local Cached = KeyCache[Master]
	if (Cached) then return Cached end
	local Keys = { Mac = Sha256.Hmac(Master, "blockcloud-mac"), Enc = Sha256.Hmac(Master, "blockcloud-enc") }
	KeyCache[Master] = Keys
	return Keys
end

function Auth.Sign(Keys, Text)
	return Codec.ToHex(Sha256.Hmac(Keys.Mac, Text):sub(1, 16))
end

function Auth.Verify(Keys, Text, Signature)
	if (type(Signature) ~= "string" or #Signature ~= 32) then return false end
	local Expected = Auth.Sign(Keys, Text)
	local Diff = 0
	for Index = 1, 32 do
		if (Expected:byte(Index) ~= Signature:byte(Index)) then Diff = Diff + 1 end
	end
	return Diff == 0
end

local Bxor, Band, Rshift, Lrotate = bit32.bxor, bit32.band, bit32.rshift, bit32.lrotate

local function Words(Bytes, Count)
	local Result = {}
	for Index = 1, Count do
		local A, B, C, D = Bytes:byte(Index * 4 - 3, Index * 4)
		Result[Index] = A + B * 256 + C * 65536 + D * 16777216
	end
	return Result
end

local function Quarter(S, A, B, C, D)
	S[A] = (S[A] + S[B]) % 4294967296; S[D] = Lrotate(Bxor(S[D], S[A]), 16)
	S[C] = (S[C] + S[D]) % 4294967296; S[B] = Lrotate(Bxor(S[B], S[C]), 12)
	S[A] = (S[A] + S[B]) % 4294967296; S[D] = Lrotate(Bxor(S[D], S[A]), 8)
	S[C] = (S[C] + S[D]) % 4294967296; S[B] = Lrotate(Bxor(S[B], S[C]), 7)
end

-- ChaCha20 (RFC 7539) with a 32-byte key and 12-byte nonce, starting at block Counter.
-- XORs Text with the keystream, so the same call encrypts and decrypts.
function Auth.ChaCha20(Key, Nonce, Counter, Text)
	local K, N = Words(Key, 8), Words(Nonce, 3)
	local Out = {}
	local Length = #Text
	local Block = 0
	local State, Work = {}, {}
	for Start = 1, Length, 64 do
		State[1], State[2], State[3], State[4] = 0x61707865, 0x3320646e, 0x79622d32, 0x6b206574
		for Index = 1, 8 do State[Index + 4] = K[Index] end
		State[13] = (Counter + Block) % 4294967296
		State[14], State[15], State[16] = N[1], N[2], N[3]
		for Index = 1, 16 do Work[Index] = State[Index] end
		for _ = 1, 10 do
			Quarter(Work, 1, 5, 9, 13)
			Quarter(Work, 2, 6, 10, 14)
			Quarter(Work, 3, 7, 11, 15)
			Quarter(Work, 4, 8, 12, 16)
			Quarter(Work, 1, 6, 11, 16)
			Quarter(Work, 2, 7, 12, 13)
			Quarter(Work, 3, 8, 9, 14)
			Quarter(Work, 4, 5, 10, 15)
		end
		local Plain = { Text:byte(Start, math.min(Start + 63, Length)) }
		local Chars = {}
		local Position = 1
		for Index = 1, 16 do
			local Word = (Work[Index] + State[Index]) % 4294967296
			for _ = 1, 4 do
				local Byte = Plain[Position]
				if (not Byte) then break end
				Chars[Position] = Bxor(Byte, Band(Word, 255))
				Word = Rshift(Word, 8)
				Position = Position + 1
			end
		end
		Block = Block + 1
		Out[Block] = string.char(table.unpack(Chars))
	end
	return table.concat(Out)
end

-- Encrypts or decrypts a message body. Nonce is any string unique to the message.
function Auth.Crypt(Key, Nonce, Text)
	return Auth.ChaCha20(Key, Sha256.Digest(Nonce):sub(1, 12), 1, Text)
end

function Auth.HashPassword(Password, Salt)
	return Sha256.Hex("blockcloud-admin|" .. Salt .. "|" .. Password)
end

return Auth
]]
Files["blockos/lib/cloud/client.lua"] = [[
-- BlockCloud client library for BlockOS apps: discovers servers, pairs with them, and makes
-- signed requests with timeouts and bounded retries. Paired servers are remembered in
-- /blockos/data/cloud/servers.dat.
--
--   local Client = BlockOS.Require("cloud/client")
--   local Nodes = Client.Discover()                      -- servers in range
--   local Result, Err = Client.Call(Server, "blockdrive", "list", { Path = "Shared" })
--
-- Calls block the calling coroutine while waiting; GUI apps run them as background tasks
-- (see cloud/tasks) so the window stays responsive.

local Config = BlockOS.Require("config")
local Protocol = BlockOS.Require("cloud/protocol")
local Auth = BlockOS.Require("cloud/auth")
local Codec = BlockOS.Require("cloud/codec")

local Client = {}

Client.Path = "/blockos/data/cloud/servers.dat"
-- Three tries with growing waits: a dead server is reported after about 7.5 seconds.
Client.Timeout = 2
Client.Retries = 2
-- NodeID -> { Online = bool, Checked = epoch, Error = text }
Client.Status = {}

local Servers = nil

local function Load()
	if (not Servers) then
		local Saved = Config.Read(Client.Path)
		Servers = type(Saved) == "table" and Saved or {}
	end
	return Servers
end

function Client.Save()
	Config.Write(Client.Path, Load())
end

function Client.Reload()
	Servers = nil
	return Load()
end

function Client.Get(NodeID)
	return Load()[NodeID]
end

function Client.List()
	local List = {}
	for _, Server in pairs(Load()) do
		table.insert(List, Server)
	end
	table.sort(List, function(A, B) return (A.Name or ""):lower() < (B.Name or ""):lower() end)
	return List
end

-- The display name used in BlockDrive: "Data Center" or the hostname.
function Client.Title(Server)
	return Server.Name or Server.Hostname or ("Computer #" .. tostring(Server.ComputerID))
end

local function Mark(Server, Online, Err)
	local Status = Client.Status[Server.NodeID] or {}
	Client.Status[Server.NodeID] = Status
	local Changed = Status.Online ~= Online
	Status.Online = Online
	Status.Checked = os.epoch("utc")
	Status.Error = Err and Protocol.Describe(Err) or nil
	if (Changed) then os.queueEvent("blockcloud_client", Server.NodeID) end
end

function Client.Online(Server)
	local Status = Client.Status[Server.NodeID]
	return Status and Status.Online
end

-- Waits for the response to request ID from ComputerID. Returns the envelope or nil on timeout.
local function Await(ComputerID, ID, ProtocolName, Timeout)
	local Timer = os.startTimer(Timeout)
	while (true) do
		local Event, A, B, C = os.pullEvent()
		if (Event == "timer" and A == Timer) then
			return nil
		elseif (Event == "rednet_message" and A == ComputerID and C == ProtocolName and type(B) == "table" and B.K == "res" and B.ID == ID) then
			os.cancelTimer(Timer)
			return B
		end
	end
end

-- Sends one request and waits for its answer, resending the same request (same ID) on timeout.
-- The server de-duplicates by ID, so a resend never runs an operation twice.
-- Opts: Keys, ClientID, Encrypt, Timeout, Retries. Returns result or nil, { Code, Message }.
function Client.Request(ComputerID, Service, Op, Args, Opts)
	Opts = Opts or {}
	if (Protocol.OpenModems() == 0) then return nil, Protocol.Error("no_modem") end
	local ProtocolName = Protocol.Name(Service)
	local Msg = Protocol.Seal({ K = "req", ID = Protocol.NewID(), Svc = Service, Op = Op, Cl = Opts.ClientID }, Args or {}, Opts.Keys, Opts.Encrypt)
	local Timeout = Opts.Timeout or Client.Timeout
	local Response
	for _ = 0, Opts.Retries or Client.Retries do
		rednet.send(ComputerID, Msg, ProtocolName)
		Response = Await(ComputerID, Msg.ID, ProtocolName, Timeout)
		if (Response) then break end
		Timeout = Timeout * 1.25
	end
	if (not Response) then return nil, Protocol.Error("unavailable") end
	if (not Protocol.Valid(Response)) then return nil, Protocol.Error("invalid") end
	local Body, Err = Protocol.Open(Response, Response.S and Opts.Keys or nil)
	if (Err) then return nil, Protocol.Error(Err) end
	if (type(Body) ~= "table") then return nil, Protocol.Error("invalid") end
	-- Unsigned answers are only believed when they are errors about the pairing itself.
	if (Opts.Keys and not Response.S and not (Body.Ok == false and (Body.Code == "not_paired" or Body.Code == "bad_signature"))) then
		return nil, Protocol.Error("bad_signature")
	end
	if (Body.Ok) then return Body.R end
	return nil, Protocol.Error(Body.Code or "internal", Body.Msg)
end

-- Broadcasts a discovery request and collects announcements for Timeout seconds.
-- Returns a list of nodes: { ComputerID, NodeID, Hostname, Name, Version, Services, Paired }.
function Client.Discover(Timeout)
	if (Protocol.OpenModems() == 0) then return nil, Protocol.Error("no_modem") end
	rednet.broadcast({ BC = Protocol.Version, K = "discover" }, Protocol.Discover)
	local Found, List = {}, {}
	local Timer = os.startTimer(Timeout or 2)
	while (true) do
		local Event, A, B, C = os.pullEvent()
		if (Event == "timer" and A == Timer) then break end
		if (Event == "rednet_message" and C == Protocol.Discover) then
			local Node = Client.HandleAnnounce(A, B)
			if (Node and not Found[Node.NodeID]) then
				Found[Node.NodeID] = true
				table.insert(List, Node)
			end
		end
	end
	table.sort(List, function(X, Y) return (X.Name or ""):lower() < (Y.Name or ""):lower() end)
	return List
end

-- Processes an announcement (from discovery or a server booting). Keeps paired servers'
-- details current and marks them online. Returns the node, or nil if the message is not one.
function Client.HandleAnnounce(Sender, Message)
	if (type(Message) ~= "table" or Message.BC ~= Protocol.Version or Message.K ~= "announce" or type(Message.Node) ~= "table") then return nil end
	local Node = Message.Node
	if (type(Node.NodeID) ~= "string" or not Node.NodeID:match("^%x+$")) then return nil end
	local Entry = {
		ComputerID = Sender,
		NodeID = Node.NodeID,
		Hostname = tostring(Node.Hostname or ""):sub(1, 24),
		Name = tostring(Node.Name or Node.Hostname or ""):sub(1, 32),
		Version = tostring(Node.Version or "?"),
		Encrypt = Node.Encrypt ~= false,
		Pairing = Node.Pairing ~= false,
		Services = type(Node.Services) == "table" and Node.Services or {}
	}
	local Server = Client.Get(Entry.NodeID)
	if (Server) then
		Entry.Paired = true
		-- An unsigned announcement may only move a server whose old computer stopped answering.
		if (Server.ComputerID ~= Sender and Client.Online(Server)) then return Entry end
		Server.ComputerID = Sender
		Server.Hostname = Entry.Hostname
		Server.Name = Entry.Name
		Server.Encrypt = Entry.Encrypt
		Server.Services = Entry.Services
		Mark(Server, true)
	end
	return Entry
end

local function Options(Server, Opts)
	local Result = { Keys = Auth.Keys(Server.Key), ClientID = Server.ClientID, Encrypt = Server.Encrypt }
	for Key, Value in pairs(Opts or {}) do Result[Key] = Value end
	return Result
end

-- Makes a signed call to a paired server (record or NodeID).
function Client.Call(Server, Service, Op, Args, Opts)
	if (type(Server) == "string") then Server = Client.Get(Server) end
	if (not Server) then return nil, Protocol.Error("not_paired") end
	local Result, Err = Client.Request(Server.ComputerID, Service, Op, Args, Options(Server, Opts))
	if (Err and Err.Code == "unavailable") then
		Mark(Server, false, Err)
	elseif (Err and Err.Code == "no_modem") then
		Mark(Server, false, Err)
	else
		Mark(Server, true)
	end
	return Result, Err
end

-- Checks a paired server is reachable and the pairing still holds; refreshes its details.
function Client.Hello(Server)
	local Result, Err = Client.Call(Server, "core", "hello", {}, { Retries = 1 })
	if (not Result) then return nil, Err end
	Server.Permission = Result.Permission
	if (type(Result.Node) == "table") then
		Server.Name = tostring(Result.Node.Name or Server.Name)
		Server.Hostname = tostring(Result.Node.Hostname or Server.Hostname)
		Server.Encrypt = Result.Node.Encrypt ~= false
		Server.Services = type(Result.Node.Services) == "table" and Result.Node.Services or Server.Services
	end
	Client.Save()
	return Result
end

function Client.Forget(NodeID, Notify)
	local Server = Client.Get(NodeID)
	if (not Server) then return end
	if (Notify) then pcall(Client.Call, Server, "core", "unpair", {}, { Retries = 0, Timeout = 1 }) end
	Load()[NodeID] = nil
	Client.Status[NodeID] = nil
	Client.Save()
end

--
-- Pairing
--

-- Asks a discovered server to pair. Returns a session whose Code must be shown to the user,
-- who reads it to the server's administrator.
function Client.StartPairing(Node, Name)
	local Session = {
		Node = Node,
		ComputerID = Node.ComputerID,
		Code = Auth.PairingCode(),
		Nonce = Auth.RandomHex(16)
	}
	local Result, Err = Client.Request(Node.ComputerID, "core", "pair_request", {
		Name = Name or os.getComputerLabel() or ("Computer #" .. os.getComputerID()),
		Nonce = Session.Nonce,
		Check = Auth.CodeCheck(Session.Code, Session.Nonce)
	})
	if (not Result) then return nil, Err end
	if (type(Result.RequestID) ~= "string" or type(Result.ServerNonce) ~= "string") then return nil, Protocol.Error("invalid") end
	Session.RequestID = Result.RequestID
	Session.ServerNonce = Result.ServerNonce
	return Session
end

-- Asks once whether the request was decided. Returns "pending", the new server record, or nil, err.
function Client.PollPairing(Session)
	local Result, Err = Client.Request(Session.ComputerID, "core", "pair_status", { RequestID = Session.RequestID }, { Retries = 1 })
	if (not Result) then return nil, Err end
	if (Result.Status ~= "approved") then return "pending" end
	local Key = Auth.DeriveKey(Session.Code, Session.RequestID, Session.Nonce, Session.ServerNonce)
	local ClientID, Permission = tostring(Result.ClientID), tostring(Result.Permission)
	if (Auth.ApprovalProof(Key, Session.RequestID, ClientID, Permission) ~= Result.Proof) then
		return nil, Protocol.Error("bad_signature", "The approval could not be verified. Pair again and check the code.")
	end
	local Node = type(Result.Node) == "table" and Result.Node or Session.Node
	local Server = {
		NodeID = Session.Node.NodeID,
		ComputerID = Session.ComputerID,
		Hostname = tostring(Node.Hostname or Session.Node.Hostname),
		Name = tostring(Node.Name or Session.Node.Name),
		ClientID = ClientID,
		Key = Codec.ToHex(Key),
		Permission = Permission,
		Encrypt = Node.Encrypt ~= false,
		Services = type(Node.Services) == "table" and Node.Services or {},
		PairedAt = os.epoch("utc")
	}
	Load()[Server.NodeID] = Server
	Client.Save()
	Mark(Server, true)
	return Server
end

-- Waits for the administrator, polling every few seconds and waking early when the server
-- nudges this computer. Cancelled when ShouldStop() returns true. Returns the server or nil, err.
function Client.WaitPairing(Session, ShouldStop, Timeout)
	local Deadline = os.clock() + (Timeout or 600)
	while (os.clock() < Deadline) do
		local Result, Err = Client.PollPairing(Session)
		if (Result ~= "pending") then return Result, Err end
		local Timer = os.startTimer(5)
		while (true) do
			local Event, A, B, C = os.pullEvent()
			if (ShouldStop and ShouldStop()) then
				os.cancelTimer(Timer)
				return nil, Protocol.Error("pairing_expired", "Pairing was cancelled.")
			end
			if (Event == "timer" and A == Timer) then break end
			if (Event == "rednet_message" and A == Session.ComputerID and C == Protocol.Name("core")
				and type(B) == "table" and B.K == "push" and B.ID == Session.RequestID) then
				os.cancelTimer(Timer)
				break
			end
		end
	end
	return nil, Protocol.Error("pairing_expired")
end

return Client
]]
Files["blockos/lib/cloud/codec.lua"] = [[
-- BlockCloud wire encoding: a canonical, length-prefixed serialisation that is safe to parse
-- (no load(), unlike textutils.unserialise), plus hex helpers and an incremental Adler-32.
-- Canonical means the same table always encodes to the same bytes, so encodings can be signed.

local Codec = {}

Codec.MaxDepth = 24

local function KeyOrder(A, B)
	local TA, TB = type(A), type(B)
	if (TA ~= TB) then return TA < TB end
	return A < B
end

local function EncodeInto(Value, Out, Depth)
	local Kind = type(Value)
	if (Kind == "nil") then
		Out[#Out + 1] = "n"
	elseif (Kind == "boolean") then
		Out[#Out + 1] = Value and "T" or "F"
	elseif (Kind == "number") then
		if (Value ~= Value or Value == math.huge or Value == -math.huge) then
			error("cannot encode " .. tostring(Value), 0)
		end
		if (Value == math.floor(Value) and math.abs(Value) < 2 ^ 53) then
			Out[#Out + 1] = string.format("i%d;", Value)
		else
			Out[#Out + 1] = string.format("f%.17g;", Value)
		end
	elseif (Kind == "string") then
		Out[#Out + 1] = "s" .. #Value .. ":"
		Out[#Out + 1] = Value
	elseif (Kind == "table") then
		if (Depth >= Codec.MaxDepth) then error("table nested too deeply", 0) end
		local Keys = {}
		for Key in pairs(Value) do
			local KeyKind = type(Key)
			if (KeyKind ~= "string" and KeyKind ~= "number") then
				error("cannot encode a " .. KeyKind .. " key", 0)
			end
			Keys[#Keys + 1] = Key
		end
		table.sort(Keys, KeyOrder)
		Out[#Out + 1] = "t"
		for _, Key in ipairs(Keys) do
			EncodeInto(Key, Out, Depth + 1)
			EncodeInto(Value[Key], Out, Depth + 1)
		end
		Out[#Out + 1] = "e"
	else
		error("cannot encode a " .. Kind, 0)
	end
end

function Codec.Encode(Value)
	local Out = {}
	EncodeInto(Value, Out, 0)
	return table.concat(Out)
end

-- Returns Value, NextIndex; errors on malformed input.
local function DecodeAt(Text, Index, Depth)
	local Tag = Text:sub(Index, Index)
	if (Tag == "n") then
		return nil, Index + 1
	elseif (Tag == "T") then
		return true, Index + 1
	elseif (Tag == "F") then
		return false, Index + 1
	elseif (Tag == "i" or Tag == "f") then
		local Finish = Text:find(";", Index + 1, true)
		if (not Finish or Finish - Index > 32) then error("bad number", 0) end
		local Number = tonumber(Text:sub(Index + 1, Finish - 1))
		if (not Number or Number ~= Number or Number == math.huge or Number == -math.huge) then error("bad number", 0) end
		return Number, Finish + 1
	elseif (Tag == "s") then
		local Colon = Text:find(":", Index + 1, true)
		if (not Colon or Colon - Index > 12) then error("bad string", 0) end
		local Length = tonumber(Text:sub(Index + 1, Colon - 1))
		if (not Length or Length < 0 or Colon + Length > #Text) then error("bad string", 0) end
		return Text:sub(Colon + 1, Colon + Length), Colon + Length + 1
	elseif (Tag == "t") then
		if (Depth >= Codec.MaxDepth) then error("table nested too deeply", 0) end
		local Result = {}
		Index = Index + 1
		while (Text:sub(Index, Index) ~= "e") do
			if (Index > #Text) then error("unterminated table", 0) end
			local Key, Value
			Key, Index = DecodeAt(Text, Index, Depth + 1)
			if (type(Key) ~= "string" and type(Key) ~= "number") then error("bad key", 0) end
			Value, Index = DecodeAt(Text, Index, Depth + 1)
			Result[Key] = Value
		end
		return Result, Index + 1
	end
	error("bad tag at " .. Index, 0)
end

-- Returns the decoded value, or nil and an error message.
function Codec.Decode(Text)
	if (type(Text) ~= "string") then return nil, "not a string" end
	local Ok, Value, Index = pcall(DecodeAt, Text, 1, 0)
	if (not Ok) then return nil, Value end
	if (Index ~= #Text + 1) then return nil, "trailing data" end
	return Value
end

function Codec.ToHex(Text)
	return (Text:gsub(".", function(Char) return string.format("%02x", Char:byte()) end))
end

function Codec.FromHex(Text)
	if (type(Text) ~= "string" or #Text % 2 ~= 0 or Text:find("[^%x]")) then return nil end
	return (Text:gsub("%x%x", function(Pair) return string.char(tonumber(Pair, 16)) end))
end

-- Adler-32 over Text, continuing from a previous checksum (1 for a fresh start).
function Codec.Adler32(Text, Previous)
	Previous = Previous or 1
	local A, B = Previous % 65536, math.floor(Previous / 65536)
	local Length = #Text
	for Start = 1, Length, 256 do
		local Bytes = { Text:byte(Start, math.min(Start + 255, Length)) }
		for Index = 1, #Bytes do
			A = A + Bytes[Index]
			B = B + A
		end
		A = A % 65521
		B = B % 65521
	end
	return B * 65536 + A
end

return Codec
]]
Files["blockos/lib/cloud/drive.lua"] = [[
-- BlockDrive client API: a remote filesystem on a paired BlockCloud server.
-- Deliberately separate from CC's fs API; remote paths are never treated as local ones.
-- Every function returns its result, or nil and an error table { Code, Message }.

local Client = BlockOS.Require("cloud/client")
local Transfer = BlockOS.Require("cloud/transfer")
local Path = BlockOS.Require("cloud/path")
local Protocol = BlockOS.Require("cloud/protocol")

local Drive = {}

local function Call(Server, Op, Args)
	return Client.Call(Server, "blockdrive", Op, Args)
end

-- Name, Shares, Free, Capacity, Used, Quota, MaxFile, Permission.
function Drive.Info(Server) return Call(Server, "info", {}) end

-- Entries: { Name, Dir, Size, Modified }, folders first.
function Drive.List(Server, Remote) return Call(Server, "list", { Path = Remote or "" }) end

function Drive.Stat(Server, Remote) return Call(Server, "stat", { Path = Remote }) end
function Drive.MakeDir(Server, Remote) return Call(Server, "mkdir", { Path = Remote }) end
function Drive.Delete(Server, Remote) return Call(Server, "delete", { Path = Remote }) end
function Drive.Move(Server, From, To) return Call(Server, "move", { From = From, To = To }) end
function Drive.Copy(Server, From, To) return Call(Server, "copy", { From = From, To = To }) end

function Drive.Rename(Server, Remote, NewName)
	if (not Path.ValidName(NewName)) then return nil, Protocol.Error("invalid_name") end
	return Drive.Move(Server, Remote, Path.Join(Path.Parent(Remote), NewName))
end

-- Opts: Overwrite, OnProgress, Cancelled.
function Drive.Upload(Server, LocalPath, Remote, Opts)
	return Transfer.Upload(Server, Remote, { Path = LocalPath }, Opts)
end

function Drive.Download(Server, Remote, LocalPath, Opts)
	Opts = Opts or {}
	Opts.Path = LocalPath
	return Transfer.Download(Server, Remote, Opts)
end

function Drive.ReadText(Server, Remote, Opts)
	return Transfer.Download(Server, Remote, Opts)
end

function Drive.WriteText(Server, Remote, Text, Opts)
	Opts = Opts or {}
	if (Opts.Overwrite == nil) then Opts.Overwrite = true end
	return Transfer.Upload(Server, Remote, { Data = Text }, Opts)
end

-- Text files BlockDrive opens in its editor.
Drive.TextTypes = { txt = true, md = true, lua = true, cfg = true, json = true, log = true, csv = true, ini = true }

function Drive.IsText(Name)
	local Extension = (Name:match("%.(%w+)$") or ""):lower()
	return Drive.TextTypes[Extension] == true or not Name:find("%.")
end

return Drive
]]
Files["blockos/lib/cloud/finder.lua"] = [[
-- Finder integration for BlockCloud, kept apart from Finder itself so Finder only needs a few
-- guarded calls. On Server Edition it adds the storage folder and logs; on the desktop it adds
-- a BlockDrive section listing paired servers, which open in the BlockDrive app.

local Link = {}

local function ClientInstalled()
	return fs.exists("/blockos/apps/blockdrive/main.lua") and fs.exists("/blockos/lib/cloud/client.lua")
end

-- Extra sidebar entries. Path entries are browsed in Finder; Launch entries open an app.
function Link.Places()
	if (BlockOS.Edition == "server") then
		local Server = BlockOS.Require("server/config")
		local Settings = Server.Settings()
		return {
			{ Text = "BlockCloud", Header = true },
			{ Text = "Storage", Path = "/" .. fs.combine(Settings.StorageRoot, ""), Icon = "\15", IconFg = colors.cyan },
			{ Text = "Logs", Path = "/blockos/data/cloud/logs", Icon = "\7", IconFg = colors.lightGray }
		}
	end
	if (not ClientInstalled()) then return {} end
	local Client = BlockOS.Require("cloud/client")
	local Items = { { Text = "BlockDrive", Header = true } }
	for _, Server in ipairs(Client.List()) do
		table.insert(Items, { Text = Client.Title(Server), Launch = { "blockdrive", { Server.NodeID } }, Icon = "\15", IconFg = colors.cyan })
	end
	if (#Items == 1) then
		table.insert(Items, { Text = "Add Server", Launch = { "blockdrive", { "add" } }, Icon = "+", IconFg = colors.cyan })
	end
	return Items
end

function Link.CanUpload()
	if (BlockOS.Edition == "server" or not ClientInstalled()) then return false end
	return #BlockOS.Require("cloud/client").List() > 0
end

-- Opens BlockDrive ready to upload a local file.
function Link.Upload(Path)
	BlockOS.Launch("blockdrive", { "upload", Path })
end

return Link
]]
Files["blockos/lib/cloud/path.lua"] = [[
-- Remote paths for BlockCloud storage. A remote path is relative to a share root and written
-- with forward slashes ("Shared/docs/notes.txt"); "" is the root. Paths are validated strictly
-- rather than resolved, so ".." and other escapes are rejected instead of being interpreted.

local Path = {}

Path.MaxLength = 240
Path.MaxComponent = 64
Path.MaxDepth = 24
-- Kept inside every storage root for staging uploads; never visible or addressable remotely.
Path.Reserved = ".blockcloud"

local Forbidden = "[%c\"%*:<>%?|]"

-- Returns the canonical form of a remote path, or nil and an error code.
function Path.Normalize(Remote)
	if (type(Remote) ~= "string") then return nil, "invalid_path" end
	if (#Remote > Path.MaxLength) then return nil, "invalid_path" end
	local Parts = {}
	for Part in Remote:gsub("\\", "/"):gmatch("[^/]+") do
		if (Part == "..") then return nil, "invalid_path" end
		if (Part ~= ".") then
			if (#Part > Path.MaxComponent or Part:find(Forbidden) or Part:match("^%s") or Part:match("%s$")) then
				return nil, "invalid_path"
			end
			if (Part:lower() == Path.Reserved) then return nil, "invalid_path" end
			Parts[#Parts + 1] = Part
		end
	end
	if (#Parts > Path.MaxDepth) then return nil, "invalid_path" end
	return table.concat(Parts, "/")
end

-- Checks a single file or folder name (for create and rename).
function Path.ValidName(Name)
	if (type(Name) ~= "string" or Name == "" or Name == "." or Name:find("[/\\]")) then return false end
	local Normal = Path.Normalize(Name)
	return Normal == Name
end

function Path.Join(Base, Name)
	if (Base == nil or Base == "") then return Name end
	if (Name == nil or Name == "") then return Base end
	return Base .. "/" .. Name
end

function Path.Parent(Remote)
	return Remote:match("^(.*)/[^/]*$") or ""
end

function Path.Name(Remote)
	return Remote:match("([^/]*)$") or Remote
end

-- True when Child is Parent itself or somewhere below it.
function Path.Within(Parent, Child)
	if (Parent == "") then return true end
	return Child == Parent or Child:sub(1, #Parent + 1) == Parent .. "/"
end

function Path.Split(Remote)
	local Parts = {}
	for Part in Remote:gmatch("[^/]+") do
		Parts[#Parts + 1] = Part
	end
	return Parts
end

-- Maps a remote path to a local path under Root. Returns the local path or nil and an error code.
-- The containment check runs on the combined path too, as a second line of defence.
function Path.Resolve(Root, Remote)
	local Normal, Err = Path.Normalize(Remote)
	if (not Normal) then return nil, Err end
	local Base = "/" .. fs.combine(Root, "")
	local Local = "/" .. fs.combine(Base, Normal)
	if (Local ~= Base and Local:sub(1, #Base + 1) ~= Base .. "/") then
		return nil, "invalid_path"
	end
	return Local, nil, Normal
end

-- Storage roots must be a dedicated folder: not the computer root, the ROM or the OS itself.
function Path.ValidRoot(Root)
	if (type(Root) ~= "string") then return false, "Storage location must be a path." end
	local Clean = fs.combine(Root, "")
	if (Clean == "") then return false, "The storage location cannot be the root of the computer." end
	local Top = Clean:match("^[^/]+")
	if (Top == "rom" or Top == "blockos" or Top == "startup" or Top == "startup.lua") then
		return false, "The storage location cannot be inside /" .. Top .. "."
	end
	if (fs.exists(Clean) and not fs.isDir(Clean)) then
		return false, "/" .. Clean .. " is a file."
	end
	return true
end

return Path
]]
Files["blockos/lib/cloud/protocol.lua"] = [[
-- BlockCloud network protocol: names, message envelopes, signing and error codes.
-- Shared by the Server Edition services and the client library.
--
-- Every BlockCloud message is a rednet table:
--   { BC = 1, K = "req" | "res" | "push" | "discover" | "announce", ID = request id,
--     Svc = service, Op = operation, Cl = client id, T = epoch ms, N = nonce,
--     E = encrypted?, B = body (Codec-encoded, maybe encrypted), S = signature }
-- Requests and responses between paired computers are signed with HMAC-SHA256 over the
-- header fields and body; pairing and discovery messages are unsigned.

local Codec = BlockOS.Require("cloud/codec")
local Auth = BlockOS.Require("cloud/auth")

local Protocol = {}

Protocol.Version = 1
-- Rednet protocol names. They are namespaced so they never collide with BlockOS Messages
-- (blockos_chat), Network (blockos_presence) or Turtles (blockos_turtle).
Protocol.Discover = "blockcloud/discover"
Protocol.Prefix = "blockcloud/svc/"
-- Requests older or newer than this are rejected as replays; CC computers share the host clock.
Protocol.MaxSkew = 120000
Protocol.MaxBody = 64 * 1024

function Protocol.Name(Service)
	return Protocol.Prefix .. Service
end

function Protocol.ServiceOf(Name)
	if (type(Name) ~= "string" or Name:sub(1, #Protocol.Prefix) ~= Protocol.Prefix) then return nil end
	return Name:sub(#Protocol.Prefix + 1)
end

Protocol.Errors = {
	timeout = "The server did not answer in time.",
	unavailable = "The server is not reachable. Check that it is on and in modem range.",
	no_modem = "No modem is attached to this computer.",
	denied = "You do not have permission to do that.",
	not_paired = "This computer is not paired with the server. Pair it again.",
	bad_signature = "The message could not be verified.",
	replay = "The request was too old or was repeated.",
	invalid = "The request was not valid.",
	invalid_path = "That path is not allowed.",
	invalid_name = "That name is not allowed.",
	not_found = "No such file or folder.",
	exists = "An item with that name already exists.",
	not_dir = "That is not a folder.",
	is_dir = "That is a folder.",
	no_space = "There is not enough storage space on the server.",
	too_large = "That file is too large for this server.",
	busy = "The server is busy. Try again in a moment.",
	transfer_lost = "The transfer was interrupted, probably because the server restarted.",
	checksum = "Data was damaged in transfer.",
	changed = "The file changed on the server during the download.",
	unknown_service = "The server does not offer that service.",
	unknown_op = "The server does not support that operation.",
	pairing_closed = "The server is not accepting new computers right now.",
	pairing_denied = "The administrator declined the pairing request.",
	pairing_expired = "The pairing request expired. Start again.",
	local_io = "A file on this computer could not be read or written.",
	internal = "The server ran into a problem. Check its logs."
}

function Protocol.Error(Code, Detail)
	return { Code = Code, Message = Detail or Protocol.Errors[Code] or Code }
end

-- A readable message for an error table or string.
function Protocol.Describe(Err)
	if (type(Err) == "table") then
		return tostring(Err.Message or Protocol.Errors[Err.Code] or Err.Code or "Unknown error")
	end
	return Protocol.Errors[Err] or tostring(Err)
end

local Token = "^[%w_%-%.]+$"

local function Signed(Msg)
	return table.concat({
		Msg.K, Msg.ID, Msg.Svc, Msg.Op, Msg.Cl or "-", string.format("%d", Msg.T), Msg.N, Msg.E and "1" or "0", Msg.B
	}, "\n")
end

-- Checks the shape of an incoming envelope before anything else looks at it.
function Protocol.Valid(Msg)
	if (type(Msg) ~= "table" or Msg.BC ~= Protocol.Version) then return false end
	if (type(Msg.K) ~= "string" or type(Msg.ID) ~= "string" or #Msg.ID > 48 or not Msg.ID:match(Token)) then return false end
	if (type(Msg.Svc) ~= "string" or not Msg.Svc:match(Token) or type(Msg.Op) ~= "string" or not Msg.Op:match(Token)) then return false end
	if (Msg.Cl ~= nil and (type(Msg.Cl) ~= "string" or not Msg.Cl:match(Token))) then return false end
	if (type(Msg.T) ~= "number" or type(Msg.N) ~= "string" or not Msg.N:match(Token)) then return false end
	if (type(Msg.B) ~= "string" or #Msg.B > Protocol.MaxBody) then return false end
	return true
end

function Protocol.NewID()
	return Auth.RandomHex(10)
end

-- Fills in the body and signature of an envelope. Keys may be nil for unsigned messages.
function Protocol.Seal(Msg, Value, Keys, Encrypt)
	Msg.BC = Protocol.Version
	Msg.T = Msg.T or os.epoch("utc")
	Msg.N = Msg.N or Auth.RandomHex(6)
	local Body = Codec.Encode(Value)
	Msg.E = (Keys ~= nil and Encrypt) and true or false
	if (Msg.E) then
		Body = Auth.Crypt(Keys.Enc, Msg.N .. Msg.ID, Body)
	end
	Msg.B = Body
	Msg.S = Keys and Auth.Sign(Keys, Signed(Msg)) or nil
	return Msg
end

-- Verifies (when Keys are given) and decodes an envelope's body. Returns the value or nil, code.
function Protocol.Open(Msg, Keys)
	if (Keys) then
		if (not Auth.Verify(Keys, Signed(Msg), Msg.S)) then return nil, "bad_signature" end
	elseif (Msg.E) then
		return nil, "invalid"
	end
	local Body = Msg.B
	if (Msg.E) then
		Body = Auth.Crypt(Keys.Enc, Msg.N .. Msg.ID, Body)
	end
	local Value, Err = Codec.Decode(Body)
	if (Err) then return nil, "invalid" end
	return Value
end

function Protocol.Fresh(Msg, Now)
	return math.abs((Now or os.epoch("utc")) - Msg.T) <= Protocol.MaxSkew
end

-- Opens every attached modem for rednet. Returns the number of modems.
function Protocol.OpenModems()
	if (not rednet) then return 0 end
	local Count = 0
	for _, Side in ipairs(peripheral.getNames()) do
		if (peripheral.getType(Side) == "modem") then
			if (not rednet.isOpen(Side)) then pcall(rednet.open, Side) end
			Count = Count + 1
		end
	end
	return Count
end

-- Lists attached modems: { Side, Wireless, Open }.
function Protocol.Modems()
	local List = {}
	for _, Side in ipairs(peripheral.getNames()) do
		if (peripheral.getType(Side) == "modem") then
			local Ok, Wireless = pcall(peripheral.call, Side, "isWireless")
			table.insert(List, { Side = Side, Wireless = Ok and Wireless or false, Open = rednet.isOpen(Side) })
		end
	end
	return List
end

return Protocol
]]
Files["blockos/lib/cloud/tasks.lua"] = [[
-- Background tasks for GUI apps. A task is a coroutine that may block on the network; the app
-- forwards its non-input events here (from Page:OnEvent) so the window keeps responding while
-- transfers run. Each app gets its own instance: BlockOS.Load("/blockos/lib/cloud/tasks.lua").

local Tasks = { List = {} }

local function Finish(Task, Ok, ...)
	for Index, Other in ipairs(Tasks.List) do
		if (Other == Task) then
			table.remove(Tasks.List, Index)
			break
		end
	end
	Task.Done = true
	if (Task.OnDone) then Task.OnDone(Ok, ...) end
end

local function Resume(Task, ...)
	local Result = table.pack(coroutine.resume(Task.Co, ...))
	if (not Result[1]) then
		Finish(Task, false, Result[2])
	elseif (coroutine.status(Task.Co) == "dead") then
		Finish(Task, true, table.unpack(Result, 2, Result.n))
	else
		Task.Filter = Result[2]
	end
end

-- Starts Fn in the background. OnDone(Ok, ...) receives its results (or false and the error).
function Tasks.Spawn(Label, Fn, OnDone)
	local Task = { Label = Label, Co = coroutine.create(Fn), OnDone = OnDone, Started = os.clock() }
	table.insert(Tasks.List, Task)
	Resume(Task)
	return Task
end

-- Feeds an event to waiting tasks. Returns true when any task finished or progressed.
function Tasks.Dispatch(Name, ...)
	if (#Tasks.List == 0 or Name == "terminate") then return false end
	local Any = false
	for _, Task in ipairs({ table.unpack(Tasks.List) }) do
		if (not Task.Done and (Task.Filter == nil or Task.Filter == Name)) then
			Resume(Task, Name, ...)
			Any = true
		end
	end
	return Any
end

function Tasks.Busy()
	return #Tasks.List > 0
end

return Tasks
]]
Files["blockos/lib/cloud/transfer.lua"] = [[
-- Chunked BlockDrive transfers. Files move in chunks of a few KB, each acknowledged by the
-- server and retried on loss; the whole file is checked with Adler-32 at the end. Downloads are
-- written to a temporary file and moved into place only when complete and verified.

local Client = BlockOS.Require("cloud/client")
local Codec = BlockOS.Require("cloud/codec")
local Protocol = BlockOS.Require("cloud/protocol")

local Transfer = {}

Transfer.ChunkTimeout = 4
Transfer.ChunkRetries = 3

local function Checksum(Data)
	local Sum = 1
	for Start = 1, #Data, 65536 do
		Sum = Codec.Adler32(Data:sub(Start, Start + 65535), Sum)
		if (#Data > 65536) then sleep(0) end
	end
	return Sum
end

function Transfer.ReadLocal(Path)
	if (not fs.exists(Path) or fs.isDir(Path)) then return nil, Protocol.Error("local_io", "Cannot read " .. Path) end
	local Handle = fs.open(Path, "rb")
	if (not Handle) then return nil, Protocol.Error("local_io", "Cannot read " .. Path) end
	local Data = Handle.readAll() or ""
	Handle.close()
	return Data
end

-- Writes Data to Path through a temporary file, so an existing file is replaced in one step.
function Transfer.WriteLocal(Path, Data)
	local Dir = fs.getDir(Path)
	if (Dir ~= "" and not fs.exists(Dir)) then fs.makeDir(Dir) end
	local Temp = Path .. ".part"
	local Handle = fs.open(Temp, "wb")
	if (not Handle) then return nil, Protocol.Error("local_io", "Cannot write " .. Path) end
	Handle.write(Data)
	Handle.close()
	if (fs.getSize(Temp) ~= #Data) then
		fs.delete(Temp)
		return nil, Protocol.Error("local_io", "Not enough space on this computer for " .. fs.getName(Path))
	end
	local Backup = Path .. ".old"
	if (fs.exists(Path)) then
		if (fs.exists(Backup)) then fs.delete(Backup) end
		fs.move(Path, Backup)
	end
	local Ok = pcall(fs.move, Temp, Path)
	if (not Ok) then
		if (fs.exists(Backup)) then fs.move(Backup, Path) end
		return nil, Protocol.Error("local_io", "Cannot write " .. Path)
	end
	if (fs.exists(Backup)) then fs.delete(Backup) end
	return true
end

local function Chunk(Server, Op, Args)
	return Client.Call(Server, "blockdrive", Op, Args, { Timeout = Transfer.ChunkTimeout, Retries = Transfer.ChunkRetries })
end

local function SendOnce(Server, Remote, Data, Sum, Opts)
	local Begin, Err = Client.Call(Server, "blockdrive", "upload_begin", { Path = Remote, Size = #Data, Sum = Sum, Overwrite = Opts.Overwrite })
	if (not Begin) then return nil, Err end
	local Size = Begin.ChunkSize
	local Count = math.ceil(#Data / Size)
	local Index = 1
	while (Index <= Count) do
		local Part = Data:sub((Index - 1) * Size + 1, Index * Size)
		local Ack, ChunkErr = Chunk(Server, "upload_chunk", { Transfer = Begin.Transfer, Index = Index, Data = Part, Sum = Codec.Adler32(Part) })
		if (not Ack) then
			if (ChunkErr.Code ~= "transfer_lost") then
				Client.Call(Server, "blockdrive", "upload_abort", { Transfer = Begin.Transfer }, { Retries = 0, Timeout = 1 })
			end
			return nil, ChunkErr
		end
		Index = tonumber(Ack.Next) or (Index + 1)
		if (Opts.OnProgress) then Opts.OnProgress(math.min(#Data, (Index - 1) * Size), #Data) end
		if (Opts.Cancelled and Opts.Cancelled()) then
			Client.Call(Server, "blockdrive", "upload_abort", { Transfer = Begin.Transfer }, { Retries = 0, Timeout = 1 })
			return nil, Protocol.Error("invalid", "Cancelled")
		end
	end
	return Client.Call(Server, "blockdrive", "upload_commit", { Transfer = Begin.Transfer }, { Timeout = 5 })
end

-- Uploads Source ({ Path = local file } or { Data = string }) to Remote.
-- Opts: Overwrite, OnProgress(done, total), Cancelled(). Returns the remote entry or nil, err.
function Transfer.Upload(Server, Remote, Source, Opts)
	Opts = Opts or {}
	local Data, Err = Source.Data, nil
	if (not Data) then
		Data, Err = Transfer.ReadLocal(Source.Path)
		if (not Data) then return nil, Err end
	end
	local Sum = Checksum(Data)
	local Result
	-- If the server restarts mid-upload the staged data is gone; start over once.
	for _ = 1, 2 do
		Result, Err = SendOnce(Server, Remote, Data, Sum, Opts)
		if (Result or not Err or (Err.Code ~= "transfer_lost" and Err.Code ~= "checksum")) then break end
	end
	return Result, Err
end

local function FetchOnce(Server, Remote, Opts)
	local Begin, Err = Client.Call(Server, "blockdrive", "download_begin", { Path = Remote }, { Timeout = 6 })
	if (not Begin) then return nil, Err end
	local Parts = {}
	local Received = 0
	for Index = 1, Begin.Chunks do
		local Piece, ChunkErr = Chunk(Server, "download_chunk", { Transfer = Begin.Transfer, Index = Index })
		if (not Piece) then return nil, ChunkErr end
		if (type(Piece.Data) ~= "string" or Codec.Adler32(Piece.Data) ~= Piece.Sum) then
			Client.Call(Server, "blockdrive", "download_end", { Transfer = Begin.Transfer }, { Retries = 0, Timeout = 1 })
			return nil, Protocol.Error("checksum")
		end
		Parts[Index] = Piece.Data
		Received = Received + #Piece.Data
		if (Opts.OnProgress) then Opts.OnProgress(Received, Begin.Size) end
		if (Opts.Cancelled and Opts.Cancelled()) then
			Client.Call(Server, "blockdrive", "download_end", { Transfer = Begin.Transfer }, { Retries = 0, Timeout = 1 })
			return nil, Protocol.Error("invalid", "Cancelled")
		end
	end
	Client.Call(Server, "blockdrive", "download_end", { Transfer = Begin.Transfer }, { Retries = 0, Timeout = 2 })
	local Data = table.concat(Parts)
	if (#Data ~= Begin.Size or Checksum(Data) ~= Begin.Sum) then return nil, Protocol.Error("checksum") end
	return Data
end

-- Downloads Remote. With Opts.Path the file is saved there; otherwise the data is returned.
-- Opts: Path, OnProgress(done, total), Cancelled().
function Transfer.Download(Server, Remote, Opts)
	Opts = Opts or {}
	local Data, Err
	for _ = 1, 2 do
		Data, Err = FetchOnce(Server, Remote, Opts)
		if (Data or (Err.Code ~= "transfer_lost" and Err.Code ~= "checksum" and Err.Code ~= "changed")) then break end
	end
	if (not Data) then return nil, Err end
	if (Opts.Path) then
		local Ok, WriteErr = Transfer.WriteLocal(Opts.Path, Data)
		if (not Ok) then return nil, WriteErr end
		return #Data
	end
	return Data
end

return Transfer
]]

local Yes = ({ ... })[1] == "--yes"

local function WriteFile(Path, Content)
	local Dir = fs.getDir(Path)
	if (Dir ~= "" and not fs.exists(Dir)) then fs.makeDir(Dir) end
	local Handle = fs.open(Path, "w")
	if (not Handle) then error("Cannot write " .. Path, 0) end
	Handle.write(Content)
	Handle.close()
end

local function Ask(Question)
	if (Yes) then return true end
	while (true) do
		write(Question .. " (y/n) ")
		local Answer = (read() or ""):lower():sub(1, 1)
		if (Answer == "y") then return true end
		if (Answer == "n") then return false end
	end
end

term.setBackgroundColor(colors.black)
term.clear()
term.setCursorPos(1, 1)
if (term.isColor()) then term.setTextColor(colors.cyan) end
print("BlockDrive " .. Version .. " for BlockOS")
if (term.isColor()) then term.setTextColor(colors.white) end

if (fs.exists("/blockos/server/boot.lua")) then
	print("This computer runs BlockOS Server Edition, which already hosts BlockDrive. Install BlockDrive on the desktop computers that should use it.")
	return
end
if (not fs.exists("/blockos/sys/desktop.lua")) then
	print("BlockDrive needs the BlockOS desktop. Install BlockOS first:")
	print("wget run https://raw.githubusercontent.com/tamayaren/BlockOS/main/install.lua")
	return
end

local Installed = fs.exists("/blockos/apps/blockdrive/main.lua")
print(Installed and "BlockDrive is installed; this updates it." or "Adds BlockDrive (network storage in the Data Center) to this computer:")
print("  /blockos/apps/blockdrive  the app (Launchpad, Finder)")
print("  /blockos/lib/cloud        BlockCloud client library")
print("  /blockos/bin/bdrive.lua   the bdrive command")
print("Nothing else is changed, and BlockOS updates keep it.")
if (not Ask(Installed and "Update BlockDrive?" or "Install BlockDrive?")) then return end

local List = {}
for Path in pairs(Files) do table.insert(List, Path) end
table.sort(List)
for Index, Path in ipairs(List) do
	WriteFile(Path, Files[Path])
	if (Index % 6 == 0) then sleep(0) end
end
WriteFile("blockos/apps/blockdrive/version.txt", Version)
WriteFile("blockos/lib/cloud/version.txt", Version)

-- Pin it to the Dock on first install, the way bundled apps are.
local SettingsPath = "/blockos/data/settings.dat"
if (not Installed and fs.exists(SettingsPath)) then
	local Handle = fs.open(SettingsPath, "r")
	local Settings = textutils.unserialise(Handle.readAll() or "")
	Handle.close()
	if (type(Settings) == "table" and type(Settings.Dock) == "table") then
		local Pinned = false
		for _, ID in ipairs(Settings.Dock) do
			if (ID == "blockdrive") then Pinned = true end
		end
		if (not Pinned) then
			table.insert(Settings.Dock, math.max(1, #Settings.Dock), "blockdrive")
			WriteFile(SettingsPath, textutils.serialise(Settings))
		end
	end
end

print()
print("Done. Open BlockDrive from the Dock or Launchpad,")
print("choose Add Server, and approve this computer on the")
print("server console. In the terminal: bdrive help")
if (BlockOS and BlockOS.Desktop) then
	os.queueEvent("blockos_apps")
else
	print("Restart BlockOS (or this computer) to see it.")
end
